using UnityEngine;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = GameObject.Find("HudRoot");
        if (hud == null) { result.Log("no HudRoot"); return; }
        var doc = hud.GetComponent<UIDocument>();
        if (doc == null || doc.rootVisualElement == null) { result.Log("no UIDocument or root"); return; }
        var root = doc.rootVisualElement;
        Walk(root, 0, result);
    }

    private static void Walk(VisualElement e, int depth, ExecutionResult r)
    {
        string prefix = new string(' ', depth * 2);
        string name = string.IsNullOrEmpty(e.name) ? "(none)" : e.name;
        string cls = "[" + string.Join(",", e.GetClasses()) + "]";
        r.Log(prefix + name + cls + " children=" + e.childCount);
        foreach (var c in e.Children()) Walk(c, depth + 1, r);
    }
}
